//! Cargo-driven `lpk.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_LpkDllInitialize@12", Some(0x72990000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "LpkDllInitialize", Some(0x7fef4000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "LpkDllInitialize", Some(0x7fef4000000u64)),
        o => panic!("lpk-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "import:usp10", "import:version", "import:user32", "import:gdi32", "import:kernel32", "import:ntdll"],
        "x86_64" => &["engine:wine", "import:usp10", "import:version", "import:user32", "import:gdi32", "import:kernel32", "import:ntdll"],
        "aarch64" => &["engine:wine", "import:usp10", "import:version", "import:user32", "import:gdi32", "import:kernel32", "import:ntdll"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/lpk",
        "dll/win32/lpk",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "dll/win32/lpk/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["LANGPACK", "UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .c_from_compile_db("lpk_shims", &["dll/win32/lpk/bidi.c", "dll/win32/lpk/direction.c", "dll/win32/lpk/lpk.c", "dll/win32/lpk/stub.c"])
        .rc("dll/win32/lpk/lpk.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/lpk/lpk.spec", "lpk.dll")
        .spec_stubs()
        .import_lib("dll/win32/usp10/usp10.spec", "usp10.dll", "usp10")
        .import_lib("dll/win32/version/version.spec", "version.dll", "version")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
